import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTitle,
  PopoverTrigger,
} from "@/components/ui/popover"
import { SCRIPT } from "@/lib/case-001"
import { cn } from "@/lib/utils"

type RunStageState = "complete" | "active" | "pending"

const RUN_STAGES = [
  { label: "Incident", afterId: null },
  { label: "Candidates", afterId: "suppliers" },
  { label: "Outreach Tasks", afterId: "outreach" },
  { label: "Claims", afterId: "claims" },
  { label: "Decision", afterId: "strategy" },
] as const

const PEBBLE_CLASS: Record<RunStageState, string> = {
  complete: "bg-foreground",
  active: "bg-muted-foreground ring-1 ring-background/40",
  pending: "bg-muted-foreground/40",
}

export function RunStatusButton({
  visible,
  approved,
}: {
  visible: number
  approved: boolean
}) {
  const states = getRunStageStates(visible, approved)
  const activeIndex = states.findIndex((state) => state === "active")
  const currentIndex = activeIndex === -1 ? RUN_STAGES.length - 1 : activeIndex
  const currentStage = RUN_STAGES[currentIndex]

  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button
            type="button"
            size="sm"
            variant="ghost"
            className="bg-transparent px-2 text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:bg-muted dark:hover:bg-muted"
            aria-label={`Sourcing run status: ${currentStage.label}`}
          >
            <span
              aria-hidden="true"
              className={cn(
                "size-2 rounded-full",
                PEBBLE_CLASS[states[currentIndex]]
              )}
            />
            {currentStage.label}
          </Button>
        }
      />
      <PopoverContent
        side="bottom"
        align="end"
        sideOffset={6}
        className="w-auto min-w-44 gap-0 p-3"
      >
        <PopoverTitle className="sr-only">Sourcing run stages</PopoverTitle>
        <ol aria-label="Sourcing run stages">
          {RUN_STAGES.map((stage, index) => (
            <RunStage key={stage.label} index={index} state={states[index]} />
          ))}
        </ol>
      </PopoverContent>
    </Popover>
  )
}

function RunStage({ index, state }: { index: number; state: RunStageState }) {
  return (
    <li
      aria-current={state === "active" ? "step" : undefined}
      className="relative flex gap-3 pb-3 last:pb-0"
    >
      <span
        aria-hidden="true"
        className={cn(
          "relative z-10 mt-0.5 size-2 shrink-0 rounded-full",
          PEBBLE_CLASS[state]
        )}
      />
      {index < RUN_STAGES.length - 1 ? (
        <span
          aria-hidden="true"
          className="absolute top-2 bottom-0 left-[3.5px] w-px bg-border"
        />
      ) : null}
      <span
        className={cn(
          "leading-none",
          state === "pending" && "text-muted-foreground"
        )}
      >
        {RUN_STAGES[index].label}
      </span>
    </li>
  )
}

function getRunStageStates(
  visible: number,
  approved: boolean
): RunStageState[] {
  const completed = RUN_STAGES.map((stage) => {
    if (stage.label === "Decision") return approved
    if (stage.afterId === null) return true
    const stepIndex = SCRIPT.findIndex((step) => step.id === stage.afterId)
    return stepIndex >= 0 && visible > stepIndex
  })
  const activeIndex = completed.findIndex((complete) => !complete)

  return completed.map((complete, index) => {
    if (complete) return "complete"
    return index === activeIndex ? "active" : "pending"
  })
}
"use client"

import { useState, type KeyboardEvent, type PointerEvent } from "react"
import { LogoIcon } from "@/components/logo"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarRail,
} from "@/components/ui/sidebar"
import { INCIDENTS } from "@/lib/case-001"
import { cn } from "@/lib/utils"

type SessionSidebarProps = {
  width: number
  onResizeStart: (event: PointerEvent<HTMLButtonElement>) => void
  onResize: (event: PointerEvent<HTMLButtonElement>) => void
  onResizeEnd: (event: PointerEvent<HTMLButtonElement>) => void
  onResizeKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void
}

export function SessionSidebar({
  width,
  onResizeStart,
  onResize,
  onResizeEnd,
  onResizeKeyDown,
}: SessionSidebarProps) {
  const [activeSession, setActiveSession] = useState<
    (typeof INCIDENTS)[number]["caseId"]
  >(INCIDENTS[0].caseId)

  return (
    <Sidebar collapsible="offcanvas" className="h-dvh">
      <SidebarHeader className="h-11 items-start justify-center border-b border-border/70 px-4 py-0">
        <LogoIcon
          aria-label="SupplyOS"
          className="size-5 text-sidebar-foreground"
        />
      </SidebarHeader>
      <SidebarContent>
        <SidebarGroup className="flex-1 py-3">
          <SidebarGroupLabel>Sessions</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {INCIDENTS.map((incident) => {
                const hasUpdate = incident.stage === "decided"

                return (
                  <SidebarMenuItem key={incident.caseId}>
                    <SidebarMenuButton
                      size="lg"
                      isActive={incident.caseId === activeSession}
                      onClick={() => setActiveSession(incident.caseId)}
                      className={cn(
                        "mb-px text-muted-foreground hover:bg-muted/60 hover:text-foreground active:bg-muted data-active:bg-muted data-active:text-foreground data-active:font-normal",
                        hasUpdate &&
                          "font-semibold text-foreground data-active:font-semibold"
                      )}
                    >
                      <span className="min-w-0">
                        <span className="block font-mono text-xs">
                          {incident.caseId}
                        </span>
                        <span
                          className={cn(
                            "block truncate text-xs text-muted-foreground",
                            hasUpdate && "text-foreground"
                          )}
                        >
                          {incident.partLabel}
                        </span>
                      </span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                )
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>
      <SidebarRail
        resizable
        aria-valuemin={10}
        aria-valuemax={20}
        aria-valuenow={Math.round(width)}
        onPointerDown={onResizeStart}
        onPointerMove={onResize}
        onPointerUp={onResizeEnd}
        onPointerCancel={onResizeEnd}
        onKeyDown={onResizeKeyDown}
      />
    </Sidebar>
  )
}

